/**
 * 工具函數
 */

/**
 * 格式化時間為 MM:SS 或 HH:MM:SS
 */
export function formatTime(seconds: number): string {
    if (!isFinite(seconds) || isNaN(seconds)) {
        return '00:00';
    }

    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    const s = Math.floor(seconds % 60);

    if (h > 0) {
        return `${h}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
    }
    return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
}

/**
 * 根據視頻總長度智能格式化時間
 * - 短視頻（<= threshold 秒）：顯示百分秒 SS.xx 或 MM:SS.xx
 * - 長視頻：使用標準格式 MM:SS 或 HH:MM:SS
 *
 * @param seconds 要格式化的時間（秒）
 * @param duration 視頻總長度（秒），用於判斷是否顯示百分秒
 * @param threshold 顯示百分秒的閾值（默認 60 秒）
 */
export function formatTimeWithPrecision(
    seconds: number,
    duration: number,
    threshold: number = 60
): string {
    if (!isFinite(seconds) || isNaN(seconds)) {
        return '00:00';
    }

    // 短視頻顯示百分秒
    if (duration > 0 && duration <= threshold) {
        const s = Math.floor(seconds);
        const cs = Math.floor((seconds - s) * 100); // 百分秒

        if (duration < 60) {
            // 總長度不足 1 分鐘：SS.xx
            return `${s.toString().padStart(2, '0')}.${cs.toString().padStart(2, '0')}`;
        } else {
            // 總長度介於 1 分鐘到閾值之間：MM:SS.xx
            const m = Math.floor(s / 60);
            const secs = s % 60;
            return `${m.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}.${cs.toString().padStart(2, '0')}`;
        }
    }

    // 長視頻使用標準格式
    return formatTime(seconds);
}

/**
 * 防抖函數
 */
export function debounce<T extends (...args: any[]) => any>(
    fn: T,
    delay: number
): (...args: Parameters<T>) => void {
    let timeoutId: number | null = null;

    return (...args: Parameters<T>) => {
        if (timeoutId) {
            clearTimeout(timeoutId);
        }
        timeoutId = window.setTimeout(() => {
            fn(...args);
        }, delay);
    };
}

/**
 * 節流函數
 */
export function throttle<T extends (...args: any[]) => any>(
    fn: T,
    limit: number
): (...args: Parameters<T>) => void {
    let inThrottle = false;

    return (...args: Parameters<T>) => {
        if (!inThrottle) {
            fn(...args);
            inThrottle = true;
            setTimeout(() => {
                inThrottle = false;
            }, limit);
        }
    };
}

/**
 * Clamp 數值到指定範圍
 */
export function clamp(value: number, min: number, max: number): number {
    return Math.max(min, Math.min(max, value));
}
